/* Chain Genius – Inventory Intelligence Engine v0.6
 * app.js
 * User interface: HTML escaping, tables, all tab views, navigation, settings and recalculation.
 * Plain script (no build step). Load order in index.html: calculations → forecasting → app → excel-import.
 */
const $=s=>document.querySelector(s);
let tab='Overview';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),H=h=>({h}),cv_=v=>v&&v.h!==undefined?v.h:esc(v);
const sv=x=>['OK','Watch','High','CRITICAL'][x],cls=x=>'s'+x;
const bars=(o,fmt=gbp)=>{const mx=Math.max(...Object.values(o),1);return Object.entries(o).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="bar"><em>${esc(k)}</em><i style="width:${v/mx*55}%"></i>${fmt(v)}</div>`).join('')};
const PAGE_WIDE=200,PAGE_NARROW=50,pgSize=()=>typeof matchMedia==='function'&&matchMedia('(max-width:600px)').matches?PAGE_NARROW:PAGE_WIDE;let shown={},tblN=0,tblMax=0,lastPg=pgSize(),rzT=null; // tables draw at most PAGE rows at a time; every row stays in R and in the Excel export, nothing is dropped
const tbl=(c,a,g)=>{const k=tab+'#'+(tblN++),n=a.length,_m=tblMax=Math.max(tblMax,n),lim=Math.max(pgSize(),shown[k]||0),part=n>lim?a.slice(0,lim):a;return `<div class="w"><table${/^(Item|SKU|Material|Order|Rank|Risk rank|Supplier|Class|Product)$/.test(c[0][0])?' class="sticky1"':''}>${g?`<tr>${g.map(z=>`<th colspan="${z[1]}" style="text-align:center;border-bottom:2px solid var(--a);color:var(--t)">${z[0]}</th>`).join('')}</tr>`:''}<tr>${c.map(x=>`<th>${x[0]}</th>`).join('')}</tr>${part.map(r=>`<tr>${c.map(x=>`<td${x[2]?' class="l"':''}>${cv_(x[1](r))}</td>`).join('')}</tr>`).join('')}</table></div>`+(n>lim?`<p class="note">Showing the first ${lim} of ${n} rows. All ${n} rows are used in the calculations and are included in the Excel export.</p><button class="p" data-more="${k}">Show ${Math.min(pgSize(),n-lim)} more</button> <button class="p" data-more="${k}" data-all="1">Show all ${n} rows${n>2000?' (may be slow on a phone)':''}</button>`:'')};
const bucket=a=>{const b={'0–7d':0,'7–30d':0,'30–60d':0,'60–90d':0,'>90d':0,'No demand':0};a.forEach(x=>{const c=x.cover;b[c==null?'No demand':c<7?'0–7d':c<30?'7–30d':c<60?'30–60d':c<=90?'60–90d':'>90d']++});return b};
const sevCell=x=>H(`<span class="${cls(x.sev)}">${sv(x.sev)}</span>`);
const itemCols=[['Item',x=>x.id],['Risk',sevCell],['Avail',x=>f(x.av)],['Position',x=>f(x.pos)],['Cover d',x=>f(x.cover,1)],['Pos. cover d',x=>f(x.pcover,1)],['LT d',x=>f(x.lt,1)],['LT source',x=>x.ltInfo.label,1],['LT basis',x=>x.ltInfo.basis,1],['Safety (workbook)',x=>f(x.ss)],['Safety (recommended)',x=>f(x.ssR)],['ROP (workbook)',x=>f(x.rop)],['ROP (recommended)',x=>f(x.ropR)],['ROP Δ%',x=>f(x.ropGap*100)],['Policy check',x=>x.verdict,1],['Value',x=>gbp(x.val)],['ABC/XYZ',x=>x.abc+'/'+x.xyz],['Confidence',x=>x.conf],['Why flagged',x=>x.why,1],['Confidence basis',x=>confExplain(x),1]];
const views={
Overview(){const r=R,a=[...r.fg,...r.rm],hi=a.filter(x=>x.sev>=2).length,ex=a.filter(x=>x.fEx).length,dqh=r.dq.filter(x=>x.sev==='High').length;
 const t=(x,n)=>tbl([['Item',x=>x.id],['Risk',sevCell],['Cover d',x=>f(x.cover,1)],['Why',x=>x.why,1]],[...x].sort((p,q)=>q.sev-p.sev||(p.cover??1e9)-(q.cover??1e9)).slice(0,n));
 return `<div class="warn">${demoBanner()} Snapshot: ${r.snap.toISOString().slice(0,10)}.</div><br>
 <div class="k"><div><b>${gbp(r.tot)}</b><span>Inventory value (on-hand × cost)</span></div><div><b>${a.length}</b><span>Items analysed (${r.fg.length} FG, ${r.rm.length} RM)</span></div><div><b class="s3">${hi}</b><span>Shortage-risk items (High+; ${SRC()})</span></div><div><b class="s2">${ex}</b><span>Excess-stock candidates (>${CFG.excess}d)</span></div><div><b>${dqh}</b><span>High-severity data issues</span></div></div><br>
 <div class="card"><h2>Financial position</h2>${tbl([['Measure',x=>x[0],1],['£',x=>x[1]],['Status',x=>x[2],1]],[['Finished-goods value',r.fgV,'Current'],['Raw-material value',r.rmV,'Current'],['Potential excess (stock above '+CFG.excess+' days cover)',r.exV,'Potential opportunity – upper bound, not a saving'],['  of which finished goods / materials',r.exF,gbp(r.exR)+' materials'],['Illustrative annual holding cost on excess @'+CFG.hold+'%',r.exV*CFG.hold/100,'Estimate – rate is an assumption'],['Cost to restore safety stock on short items',r.shV,'Exposure'],['Verified benefit',0,'None – requires client validation']].map(x=>[x[0],gbp(x[1]),x[2]]))}
 <p class="note">Top 10 items hold ${f(r.top10,1)}% of inventory value. Turnover: FG ${f(r.cogsF/r.fgV,1)}×/yr, materials ${f(r.cogsR/r.rmV,1)}×/yr (est. annual usage × cost ÷ on-hand value).</p></div>
 <div class="card"><h2>Value by product family</h2>${bars(r.fam)}<h2>Value by material group</h2>${bars(r.rg)}</div>
 <div class="card"><h2>Stock cover (available ÷ daily demand)</h2><b>Finished goods</b>${bars(bucket(r.fg),f)}<b>Raw materials</b>${bars(bucket(r.rm),f)}</div>
 <div class="card"><h2>Highest-risk products</h2>${t(r.fg,6)}</div><div class="card"><h2>Highest-risk materials</h2>${t(r.rm,8)}</div>
 <div class="card"><h2>Supplier risk (ranked by at-risk materials)</h2><p class="note">Ranked by the number of at-risk materials (High or Critical under the current policy and supply settings), then by supplier score (lower is worse). Suppliers whose overall score cannot defensibly be calculated (no delivery history, or invalid purchase-order data) are shown as Not Assessed — Insufficient Evidence (they are not treated as good or bad, and a data problem is not a performance classification), and their materials still count. The supplier score formula is unchanged; see the Suppliers tab.</p>${tbl([['Rank',x=>r.supRisk.indexOf(x)+1],['Supplier',x=>x.id+' '+x.name,1],['Risk class',x=>x.cat,1],['Evidence',x=>evTxt(x),1],['Score',x=>f(x.score)],['At-risk materials',x=>x.risk],['Materials supplied',x=>x.mats],['Share at risk',x=>x.mats?f(x.risk/x.mats*100)+'%':'–']],r.supRisk.slice(0,5))}</div>`},
'Finished goods'(){return `<div class="card"><p class="note">Risk is driven by the ${CFG.pol?'RECOMMENDED (calculated)':'WORKBOOK'} policy; both are shown. Available = on-hand − allocated. Position = available + on-order. Lead time source and calculation basis are shown in the LT source / LT basis columns (supplied, calculated or estimated; only labelled Supplied if it came from the workbook). Finished-goods safety stock assumes a fixed production time (see Reorder policy). Sorted by risk.</p>${tbl(itemCols,[...R.fg].sort((p,q)=>q.sev-p.sev||(p.cover??1e9)-(q.cover??1e9)))}</div>`},
Materials(){return `<div class="card"><p class="note">Risk is driven by the ${CFG.pol?'RECOMMENDED (calculated)':'WORKBOOK'} policy. Usage is ESTIMATED from BOM × units sold × (1+scrap). Risk-adjusted lead time = stated + average supplier lateness. Exposed £/mo = monthly sales value of products using the material.</p>${tbl([...itemCols.slice(0,7),['Est use/mo',x=>f(x.m)],['Products',x=>x.n],['Exposed £/mo',x=>gbp(x.exposed)],...itemCols.slice(7)],[...R.rm].sort((p,q)=>q.sev-p.sev||(p.cover??1e9)-(q.cover??1e9)))}</div>`}};
const ORDER=['Overview','Health','Finished goods','Materials','MRP','Production feasibility','Excess & dead stock','Policy comparison','Reorder policy','Forecast accuracy','Demand forecast','Suppliers','Data quality','Client questions','Data confidence','Summary','Settings'];
const abcRows=(a,t)=>{const tv=a.reduce((q,x)=>q+x.val,0)||1,ta=a.reduce((q,x)=>q+x.ann,0)||1;let c=0;return ['A','B','C'].map(k=>{const g=a.filter(x=>x.abc===k),p=g.reduce((q,x)=>q+x.ann,0)/ta*100;c+=p;return [t+' '+k,g.length,f(p,1)+'%',f(c,1)+'%',f(g.reduce((q,x)=>q+x.val,0)/tv*100,1)+'%']})};
views.Health=()=>{const a=[...R.fg,...R.rm],cats=['Excellent','Healthy','Monitor','At risk','Critical'],c=[['Item',x=>x.id],['Score',x=>x.score],['Category',x=>x.cat,1],['Points lost',x=>x.hp.map(y=>'-'+y[0]+' '+y[1]).join('; ')||'none',1]],s=[...a].sort((p,q)=>p.score-q.score);
 return `<div class="card"><div class="k"><div><b>${f(mean(a.map(x=>x.score)),1)}</b><span>Overall health (simple average)</span></div>${cats.map(k=>`<div><b>${a.filter(x=>x.cat===k).length}</b><span>${k}</span></div>`).join('')}</div><p class="note">Score = 100 minus penalty points: stockout / below safety stock 30 or 20, cover below lead time 20 or 8, below reorder point 8, excess cover up to 25, demand variability 10 or 4, unreliable supplier 8, forecast bias 6, data-quality flag 6. These weights are judgement calls to be tuned on real data.</p></div><div class="card"><h2>Lowest scores</h2>${tbl(c,s.slice(0,12))}</div><div class="card"><h2>Highest scores</h2>${tbl(c,s.slice(-6).reverse())}</div>
 <div class="card"><h2>ABC classification (annual consumption value; A ≤${CFG.abcA}% cumulative, B ≤${CFG.abcB}%)</h2>${tbl([['Class',x=>x[0],1],['Items',x=>x[1]],['% of annual value',x=>x[2]],['Cumulative %',x=>x[3]],['% of stock value',x=>x[4]]],[...abcRows(R.fg,'FG'),...abcRows(R.rm,'RM')])}</div>`};
views['Excess & dead stock']=()=>{const a=[...R.fg,...R.rm].filter(x=>x.cls!=='Active').sort((p,q)=>q.val-p.val);
 return `<div class="card"><p class="note">Months since last demand uses monthly buckets. Materials use ESTIMATED BOM-derived demand. Temporary low demand never makes an item obsolete: that needs 6+ months with none. ${a.some(x=>x.cls==='Potentially obsolete')?'':'No item currently meets that test.'}</p><p>${a.length} items, on-hand ${gbp(a.reduce((q,x)=>q+x.val,0))}, potential excess ${gbp(a.reduce((q,x)=>q+x.exVal,0))}.</p>${tbl([['Item',x=>x.id],['Description',x=>x.name,1],['Qty',x=>f(x.oh)],['Value',x=>gbp(x.val)],['Months since demand',x=>x.msl??'–'],['Cover d',x=>f(x.cover)],['Class',x=>x.cls,1],['Potential excess',x=>gbp(x.exVal)],['Action',x=>x.act,1]],a)}</div>`};
views.Suppliers=()=>`<div class="card"><p class="note">Score (0–100) = 50% on-time rate + 20% lead-time stability (100 − 200×CV of lead time) + 15% fill rate (each PO line counts at most its ordered quantity, so an over-delivery never offsets a shortage elsewhere; excess units are shown separately) + 15% lateness (100 − 10 per average day late). Risk: ${CFG.supLow}+ Low, ${CFG.supMed}–${CFG.supLow-1} Medium, under ${CFG.supMed} High. Only POs received by the snapshot (${R.snap.toISOString().slice(0,10)}) are scored; others count as outstanding. Each metric uses only the received lines whose own inputs are valid: on-time and lateness need a valid promised date, lead-time stability needs valid order and received dates, fill rate needs valid numeric quantities (a blank, text, negative or zero-ordered quantity is unknown, not zero; numeric text such as "120" is not converted and is flagged in Data quality). If any of the four metrics has no valid line the overall score is not calculated and the supplier is shown as ${SUP_NA}; the metrics that can still be assessed are shown. Evidence: Adequate = at least ${CFG.supMinPO} valid lines behind every metric; Limited = fewer; None = at least one metric has no valid line. A Data problem is not a performance classification, and the supplier's materials still count in risk. Assessment separates a performance problem (score under ${CFG.supMed} with adequate evidence) from a possible problem on limited history. The table is ordered by at-risk materials, then score, matching the Overview.</p>${tbl([['Risk rank',x=>R.supRisk.indexOf(x)+1],['Score rank',x=>R.sup.indexOf(x)+1],['Supplier',x=>x.id+' '+x.name,1],['Score',x=>f(x.score)],['Risk class',x=>x.cat,1],['Evidence',x=>evTxt(x),1],['Assessment',x=>x.assess,1],['POs scored',x=>x.n],['On-time %',x=>f(x.otd)],['Delayed',x=>x.delayed],['Short',x=>x.shortN],['Outstanding at snapshot',x=>x.excl],['Avg days late',x=>f(x.late,1)],['Stated LT',x=>x.stated],['Observed LT',x=>f(x.ltA,1)],['LT σ',x=>f(x.ltS,1)],['Fill %',x=>f(x.fill,1)],['Over-delivered units',x=>x.over?H(`<span class="s1">${f(x.over)}</span>`):'0'],['Over-delivered lines',x=>x.overN],['Materials',x=>x.mats],['At-risk mats',x=>x.risk]],R.supRisk)}</div>
 ${prCard()}`;
views['Data quality']=()=>{const o={High:0,Medium:1,Low:2},e=R.dq.filter(x=>x.sev==='High'),act={'Data quality':'Correct the source data and re-import','Operational':'Investigate with operations','Reconciliation':'Reconcile systems before relying on affected figures'},p=R.po;
 return `<div class="k"><div><b class="s3">${e.length}</b><span>Errors</span></div><div><b class="s2">${R.dq.length-e.length}</b><span>Warnings</span></div><div><b>${new Set(R.dq.map(x=>x.sheet)).size}</b><span>Sheets affected</span></div></div><br>${poReconCard()}<div class="card"><p class="note"><b>Data quality</b>: fix the data first. <b>Operational</b>: a real-world issue. <b>Reconciliation</b>: two sources disagree.</p>${tbl([['Severity',x=>x.sev==='High'?'Error':'Warning'],['Kind',x=>x.kind,1],['Sheet',x=>x.sheet,1],['Issue',x=>x.msg,1],['Examples',x=>x.ex,1],['Suggested action',x=>act[x.kind]||'Review',1]],[...R.dq].sort((a,b)=>o[a.sev]-o[b.sev]))}</div>`};
const reconCard=()=>{const a=R.recon,g=a.filter(x=>x.gap>0);return `<h2>Per-material reconciliation</h2><p class="note">All ${a.length} materials have POs on file (${Math.min(...a.map(x=>x.n))}–${Math.max(...a.map(x=>x.n))} each), none duplicated or unlinked. ${g.length} of ${a.length} materials show more on-order in the inventory than the POs support; gap value ${gbp(g.reduce((q,x)=>q+x.val,0))} at standard cost. The gap is spread across materials (top 10 = ${f([...a].sort((p,q)=>q.gap-p.gap).slice(0,10).reduce((q,x)=>q+x.gap,0)/(a.reduce((q,x)=>q+x.gap,0)||1)*100)}% of it), so it looks systemic, not a few bad records. Largest gaps:</p>${tbl([['Material',x=>x.id],['Inventory on-order',x=>f(x.inv)],['PO outstanding at snapshot',x=>f(x.po)],['Gap',x=>f(x.gap)],['Gap £',x=>gbp(x.val)],['POs on file',x=>x.n]],[...a].sort((p,q)=>q.gap-p.gap).slice(0,10))}`};
views['Policy comparison']=()=>{const A=[...R.fg,...R.rm],B=Object.fromEntries([...R.alt.fg,...R.alt.rm].map(x=>[x.id,x])),ch=A.filter(x=>x.sev!==B[x.id].sev).map(x=>CFG.pol?{id:x.id,a:B[x.id],b:x}:{id:x.id,a:x,b:B[x.id]}).sort((p,q)=>(q.b.sev-q.a.sev)-(p.b.sev-p.a.sev)||q.b.sev-p.b.sev);
 return `<div class="card"><p class="note">Risk class under the WORKBOOK policy (stated safety stock and reorder point) vs the CALCULATED policy (z=${CFG.z}; lead time includes supplier lateness; indicative, assumes normally distributed demand). ${ch.length} of ${A.length} items change class.</p>${tbl([['Item',x=>x.id],['Workbook policy',x=>sv(x.a.sev),1],['Calculated policy',x=>sv(x.b.sev),1],['Effect',x=>x.b.sev>x.a.sev?'Riskier when calculated':'Safer when calculated',1],['Safety wb→calc',x=>f(x.a.ss)+' → '+f(x.a.ssR)],['ROP wb→calc',x=>f(x.a.rop)+' → '+f(x.a.ropR)],['Avail cover d',x=>f(x.a.cover,1)],['Lead time d',x=>f(x.a.lt,1)]],ch)}</div>${supCard()}`};
views.MRP=()=>{const a=[...mrp()].sort((p,q)=>['ORDER NOW','Order soon','Plan','Covered'].indexOf(p.st)-['ORDER NOW','Order soon','Plan','Covered'].indexOf(q.st)||q.val-p.val),n=a.filter(r=>r.net>0);
 return `<div class="card"><div class="k"><div><b class="s3">${a.filter(r=>r.st==='ORDER NOW').length}</b><span>Order now (${SRC()})</span></div><div><b>${n.length}</b><span>Materials with net requirement</span></div><div><b>${gbp(n.reduce((q,r)=>q+r.val,0))}</b><span>Total replenishment over horizon (standard cost), not a shortage figure</span></div></div>
 <p class="note"><b>Workbook data:</b> on-hand, allocated, MOQ, lead time, open POs (promised dates). <b>Calculated estimate:</b> gross requirement = ${CFG.hor} months × estimated monthly usage (BOM × units sold × (1+scrap), demand held flat at its average; no forecast applied yet). Net = gross + safety stock (${CFG.pol?'calculated':'workbook'} policy) − available − scheduled receipts. Scheduled receipts = ${CFG.sup===1?'inventory-recorded On_Order_Qty (<b>unverified</b>)':'POs not received by the snapshot (verified)'}; the comparison column shows net under the other source. Order-by = estimated stock-out date minus risk-adjusted lead time. Suggested quantities are rounded up to MOQ; confirm supplier terms before ordering.</p>
 ${tbl([['Material',x=>x.x.id],['Status',x=>H(`<span class="${{'ORDER NOW':'s3','Order soon':'s2',Plan:'s1',Covered:'s0'}[x.st]}">${x.st}</span>`)],['Available',x=>f(x.x.av)],['Receipts (POs)',x=>f(x.rq)],['Gross req.',x=>f(x.gross)],['Safety',x=>f(x.x.ssU)],['Net req.',x=>f(x.net)],['MOQ',x=>f(x.x.moq)],['Suggest qty',x=>f(x.qty)],['£',x=>gbp(x.val)],['Stock-out ~',x=>x.out],['Order by',x=>x.by],['Net, other supply source',x=>f(x.netU)],['Affects',x=>x.aff,1]],a)}</div>`};
const supCard=()=>{const A=CFG.sup===1?R.altS:R,Bm=Object.fromEntries([...(CFG.sup===1?R:R.altS).fg,...(CFG.sup===1?R:R.altS).rm].map(x=>[x.id,x])),ch=[...A.fg,...A.rm].filter(x=>x.sev!==Bm[x.id].sev).map(x=>({a:x,b:Bm[x.id]}));
 return `<div class="card"><h2>Supply source comparison</h2><p class="note">PO-verified outstanding supply vs inventory-recorded on-order. ${ch.length} items change risk class. Finished-goods on-order has no verifiable source, so it is 0 in the verified view.</p>${tbl([['Item',x=>x.a.id],['PO-verified',x=>sv(x.a.sev),1],['Inventory on-order',x=>sv(x.b.sev),1],['On-order verified→recorded',x=>f(x.a.oo)+' → '+f(x.b.oo)],['Pos. cover d',x=>f(x.a.pcover,1)+' → '+f(x.b.pcover,1)]],ch)}</div>`};
views['Production feasibility']=()=>{const F=feas(),a=F.rows,n=k=>a.filter(r=>r.status===k).length,cl={Feasible:'s0','Feasible with incoming materials':'s1','At risk':'s2','Material shortage':'s3','Insufficient information':'s2'};
 return `<div class="card">${F.sim?'<div class="warn">SIMULATED: the workbook has no open or planned production orders ('+R.prRows.length+' orders found, none open), so this tests one month of average demand per product, one order per day from the snapshot. These are not real orders.</div><br>':''}<div class="k"><div><b class="s0">${n('Feasible')}</b><span>Feasible</span></div><div><b class="s1">${n('Feasible with incoming materials')}</b><span>With incoming</span></div><div><b class="s2">${n('At risk')}</b><span>At risk</span></div><div><b class="s3">${n('Material shortage')}</b><span>Material shortage</span></div></div>
 <p class="note">Orders are processed in start-date order and draw on a shared pool of available stock (on-hand − allocated) and scheduled receipts (${CFG.sup===1?'inventory on-order, UNVERIFIED, assumed to arrive after the lead time':'open POs at their promised dates, verified'}). Shortage orders do not reserve stock. Required quantity = order qty × BOM qty × (1+scrap), an estimate. Delay refers to materials only; machine capacity and routing are not in the data and are not assessed. Where no receipt is scheduled, availability assumes a new order today at the risk-adjusted lead time.</p>
 ${tbl([['Order',x=>x.o.id],['SKU',x=>x.o.sku],['Qty',x=>f(x.o.q)],['Start',x=>x.start],['Status',x=>H(`<span class="${cl[x.status]}">${esc(x.status)}</span>`),1],['Materially delayed?',x=>x.delay,1],['Blocking materials (short qty, available ~)',x=>x.bl.slice(0,4).map(b=>b.id+' short '+f(b.sh)+' ('+x.sd(b.when)+(b.sched?'':' if ordered now')+')').join('; ')+(x.bl.length>4?' +'+(x.bl.length-4)+' more':''),1],['Confidence',x=>x.conf],['Basis',x=>x.why,1]],a)}</div>`};
views['Client questions']=()=>`<div class="card"><p class="note">Generated from discrepancies and gaps found in the uploaded data. Each question names the evidence that triggered it.</p>${tbl([['Priority',x=>x.pri],['Question for the client',x=>x.q,1],['Why we are asking',x=>x.why,1],['Evidence in data',x=>x.ev,1]],qs())}</div>`;
views.Summary=()=>{const a=[...R.fg,...R.rm],cr=a.filter(x=>x.sev===3),m=mrp(),on=m.filter(r=>r.st==='ORDER NOW').length,P=R.po,ws=R.sup.filter(s=>s.cat==='High risk'),ex=a.filter(x=>x.fEx),ins=a.filter(x=>x.verdict==='Existing ROP insufficient').length,expo=R.fg.filter(x=>x.sev===3).reduce((q,x)=>q+x.m*x.price,0),F=feas().rows,sn=Math.min(...R.sup.filter(s=>s.score!==null).map(s=>Math.min(s.nOtd,s.nLt,s.nFill)),Infinity),na=R.sup.filter(s=>s.score===null).length,
 rec=[['Secure supply for the '+cr.length+' critical items ('+cr.slice(0,6).map(x=>x.id).join(', ')+')','No available stock, or position cover below lead time. Finished goods affected carry about '+gbp(expo)+' of monthly sales value (exposure, not a loss).','Expedite or place orders for the listed items; confirm supplier dates.',minC(cr)],
  ['Verify on-order quantities before ordering','Inventory on-order exceeds snapshot-dated POs by '+f(P.invRM-P.snap)+' units (raw materials); results change with the supply source setting.','Obtain open PO ledger; reconcile with the inventory system.','High'],
  ['Review excess stock ('+ex.length+' items)','Stock above '+CFG.excess+' days of cover: potential opportunity '+gbp(R.exV)+' (upper bound, not a saving; threshold is an assumption).','Reduce future purchasing or production for these items; review forecasts.','Medium'],
  ['Manage weak suppliers ('+(ws.map(s=>s.id).join(', ')||'none')+')','Supplier score under '+CFG.supMed+' among assessed suppliers'+(isFinite(sn)?' (at least '+sn+' PO(s) each).':': no supplier could be assessed.')+(na?' '+na+' supplier(s) are '+SUP_NA+' (no delivery history, or invalid purchase-order data) and are not counted as problems.':''),'Agree delivery performance targets and lead-time buffers.',!isFinite(sn)?'Low':sn>=CFG.ltMinSup?'High':sn>=CFG.supMinPO?'Medium':'Low'],
  ['Review reorder points ('+ins+' items look too low)','Workbook reorder points do not reflect lead time and supplier lateness for those items (calculated policy is indicative).','Recalculate reorder points per item and agree the policy.','Medium']];
 return `<div class="card"><h2>Management summary – ${esc(R.title)}</h2><div class="warn">${demoBanner()} Items marked (est.) are calculated estimates, not measured results.</div><br>
 <div class="k"><div><b>${gbp(R.tot)}</b><span>Inventory value (workbook data)</span></div><div><b class="s3">${cr.length}</b><span>Critical items (calc.)</span></div><div><b>${on}</b><span>Materials to order now (est.; ${SRC()})</span></div><div><b>${gbp(R.exV)}</b><span>Potential excess (est., not a saving)</span></div></div>
 <h2>Recommendations</h2>${tbl([['Priority',x=>x[4]],['Recommendation',x=>x[0],1],['Reason and financial effect',x=>x[1],1],['Suggested action',x=>x[2],1],['Confidence',x=>x[3]]],rec.map((r,i)=>[...r,i+1]))}
 <h2>Limitations</h2><p class="note">Supply source: ${['PO-verified','inventory-recorded (unverified)','PO-verified (comparison available)'][CFG.sup]}. Material usage is estimated from the BOM and sales, not recorded. MRP holds demand flat at its average (the forecasts are not yet fed into MRP). History is ${R.fg[0]?R.fg[0].h.length:0} months. Production feasibility ${feas().sim?'uses illustrative orders (no open orders in data)':'uses workbook open orders'} and ignores capacity. ${R.dq.filter(x=>x.sev==='High').length} high-severity data issues remain; see Client questions (${qs().length}). Confidence by area: see the Data confidence tab. Feasibility result: ${F.filter(r=>r.status==='Material shortage').length} of ${F.length} orders short of materials.</p><button class="p" onclick="print()">Print / save as PDF</button></div>`};
const evTxt=x=>x.evid+' ('+x.n+' POs'+(x.nFill<x.n?', '+x.nFill+' with valid quantities':'')+(x.nOtd<x.n?', '+x.nOtd+' with a valid promised date':'')+')'; // evidence counts valid eligible records; identical to the old text when every line is valid
const SRC=()=>['PO-verified supply','inventory-recorded on-order, UNVERIFIED','PO-verified supply, comparison on'][CFG.sup];
const banner=()=>`<div class="warn">Supply source: <b>${SRC()}</b> · Risk policy: <b>${CFG.pol?'calculated':'workbook'}</b> · Demand basis: <b>${CFG.basis}-month average</b>. Shortage, MRP and feasibility figures depend on these settings (Settings tab).</div><br>`;
let pf='all',fsku=null;
views['Reorder policy']=()=>{const A=[...R.fg,...R.rm],V={ins:'Existing ROP insufficient',exc:'Existing ROP possibly excessive',ok:'Broadly aligned'},a=A.filter(x=>pf==='all'||x.verdict===V[pf]),
 why=x=>{if(!(x.d>0))return 'No demand, so no calculation.';const dl=x.d*x.lt,rd=x.rop/x.d;return x.verdict===V.ins?`Workbook ROP covers ${f(rd,1)} days of demand but lead time is ${f(x.lt,1)} d: demand during lead time is ${f(dl)} units, leaving ${f(x.rop-dl)} before any safety stock.`:x.verdict===V.exc?`Workbook ROP covers ${f(rd,1)} days of demand against a ${f(x.lt,1)} d lead time (${f(x.rop/(dl||1),1)}× lead-time demand); calculated ROP is ${f(x.ropR)}.`:'Within ±20% of the calculated value.'};
 return `<div class="card">${[['all','All'],['ins','Insufficient'],['exc','Possibly excessive'],['ok','Aligned']].map(([k,t])=>`<button data-pf="${k}" class="${pf===k?'p':''}">${t}</button>`).join(' ')}<p class="note">Calculated: daily demand d = monthly average ÷ 30.4; lead time LT = stated plus average supplier lateness (finished goods: average production duration); safety stock = z × √(LT×σd² + d²×σLT²), z=${CFG.z}; ROP = d×LT + safety stock. Assumes normally distributed, independent demand and lead times, so it is indicative, not a recommendation. Finished goods assume a fixed production time: the calculated safety stock includes demand variability but no production-time variability (σLT is shown as 0 for finished goods even where production orders vary), so it may be understated for products whose production times vary. Verdict compares workbook and calculated ROP (±20%). ${a.length} items shown.</p>${tbl([['Item',x=>x.id],['d/day',x=>f(x.d,1)],['σ monthly',x=>f(x.sg,1)],['LT d',x=>f(x.lt,1)],['LT source',x=>x.ltInfo.label,1],['σLT d',x=>f(x.ltS,1)],['SS wb',x=>f(x.ss)],['SS calc',x=>f(x.ssR)],['ROP wb',x=>f(x.rop)],['ROP calc',x=>f(x.ropR)],['Δ%',x=>f(x.ropGap*100)],['Verdict',x=>x.verdict,1],['Why',x=>why(x),1]],a)}</div>`};
const chart=(x,F)=>{const W=640,Hh=230,p=34,h=x.h,n=h.length,N=n+12,all=[...h,...F.hi,...(x.fc||[])].filter(isFinite),mx=Math.max(...all,1)*1.1,X=i=>p+i*(W-2*p)/(N-1),Y=v=>Hh-p-v/mx*(Hh-2*p),pl=(a,o,c,d)=>`<polyline fill="none" stroke="${c}" stroke-width="2" ${d?`stroke-dasharray="${d}"`:''} points="${a.map((v,i)=>X(i+o).toFixed(1)+','+Y(v).toFixed(1)).join(' ')}"/>`,
 band=[...F.hi.map((v,j)=>X(n+j).toFixed(1)+','+Y(v).toFixed(1)),...F.lo.map((v,j)=>X(n+11-j).toFixed(1)+','+Y(F.lo[11-j]).toFixed(1))].join(' ');
 return `<svg viewBox="0 0 ${W} ${Hh}" width="100%" role="img" aria-label="Demand and forecast for ${esc(x.id)}"><line x1="${p}" y1="${Y(0)}" x2="${W-p}" y2="${Y(0)}" stroke="var(--b)"/><line x1="${X(n-.5)}" y1="${p-10}" x2="${X(n-.5)}" y2="${Y(0)}" stroke="var(--b)" stroke-dasharray="3 3"/><polygon points="${band}" fill="var(--g)" opacity=".15"/>${x.fc&&x.fc.length===n?pl(x.fc,0,'var(--o)','5 4'):''}${pl(h,0,'var(--a)')}${pl([h[n-1],...F.f],n-1,'var(--g)','2 3')}<text x="${p}" y="${p-14}" font-size="11" fill="var(--m)">units/month (max ${f(mx/1.1)})</text><text x="${X(n-.5)+4}" y="${p-2}" font-size="10" fill="var(--m)">forecast →</text></svg>`};
views['Demand forecast']=()=>{const A=fcAll(),ok=R.fg.filter(x=>A[x.id].ok);if(!ok.length)return '<div class="card">Fewer than 6 months of demand history: no statistical forecast can be produced.</div>';
 const sel=fsku&&A[fsku]&&A[fsku].ok?fsku:ok[0].id,x=R.fg.find(y=>y.id===sel),F=A[sel],S=k=>ok.reduce((q,y)=>q+A[y.id][k],0),n0=A[ok[0].id].n,cnt=t=>ok.filter(y=>A[y.id].trend===t).length;
 return `<div class="card"><div class="warn">ESTIMATES from statistical methods applied to ${n0} months of history. Not guaranteed; accuracy is measured only by back-testing on past months, never assumed.${n0<24?' With under 24 months, seasonality cannot be tested.':''}${ok.length<R.fg.length?' '+(R.fg.length-ok.length)+' products have under 6 months and are not forecast.':''}</div><br>
 <div class="k"><div><b>${f(S('act12'))}</b><span>Units sold, last 12 months (actual)</span></div><div><b>${f(S('s3'))}</b><span>Forecast, next 3 months (est.)</span></div><div><b>${f(S('s6'))}</b><span>Next 6 months (est.)</span></div><div><b>${f(S('s12'))}</b><span>Next 12 months (est.)</span></div><div><b>${cnt('Rising')}/${cnt('Falling')}</b><span>Rising / falling trends</span></div></div>
 <h2>Product chart</h2><select id="fsel" style="width:auto">${ok.map(y=>`<option value="${esc(y.id)}"${y.id===sel?' selected':''}>${esc(y.id)} ${esc(y.name)}</option>`).join('')}</select>${chart(x,F)}
 <p class="note"><span style="color:var(--a)">━</span> actual demand · <span style="color:var(--o)">╌</span> existing workbook forecast (recorded) · <span style="color:var(--g)">┈</span> statistical forecast (${esc(FNAME[F.best])}) with indicative 80% range, assuming roughly normal, independent errors (based on only ${F.bt[F.best].pts} back-test points); these are not guaranteed demand limits, only a rough guide. Trend: ${F.trend}${F.trend!=='No significant trend'?' ('+f(F.tp,1)+'%/month)':''}. Seasonality: ${F.seas?(F.seas.det?'detected':'not detected'):'not testable'}.</p>
 <h2>Method comparison for ${esc(sel)} (back-test: each method forecasts the next month from earlier months only)</h2>${tbl([['Method',x=>FNAME[x.k]||x.k,1],['WAPE %',x=>f(x.w*100,1)],['Bias %',x=>f(x.b*100,1)],['Months tested',x=>x.p],['Used',x=>x.u,1]],[...F.meth.map(k=>({k,w:F.bt[k].wape,b:F.bt[k].bias,p:F.bt[k].pts,u:k===F.best?'Selected':''})),...(F.wb!=null?[{k:'Existing workbook forecast (recorded, same months)',w:F.wb,b:null,p:F.bt[F.best].pts,u:''}]:[])])}
 <h2>All products</h2>${tbl([['SKU',x=>x.id],['Method',x=>FNAME[A[x.id].best],1],['Last 12m',x=>f(A[x.id].act12)],['Next 3m',x=>f(A[x.id].s3)],['Next 6m',x=>f(A[x.id].s6)],['Next '+Math.min(12,Math.max(3,CFG.fcH||12))+'m',x=>f(A[x.id].f.slice(0,Math.min(12,Math.max(3,CFG.fcH||12))).reduce((q,v)=>q+v,0))],['Trend',x=>A[x.id].trend,1],['3m range (80%)',x=>f(Math.max(0,A[x.id].s3-1.28*A[x.id].rm*Math.sqrt(3)))+'–'+f(A[x.id].s3+1.28*A[x.id].rm*Math.sqrt(3))],['Uncertainty',x=>A[x.id].unc,1],['Existing fcst WAPE %',x=>A[x.id].wb==null?'n/a':f(A[x.id].wb*100)],['Best method WAPE %',x=>f(A[x.id].wbBest*100)],['Confidence',x=>A[x.id].conf],['Recommendation',x=>A[x.id].rec,1],['Basis',x=>A[x.id].confWhy,1]],ok)}</div>`};
function show(){lastPg=pgSize();tblMax=0;$('#nav').innerHTML=ORDER.filter(k=>views[k]).map(k=>`<button class="${k===tab?'on':''}" data-t="${k}"${k===tab?' aria-current="page"':''}>${k}</button>`).join('');tblN=0;$('#v').innerHTML=banner()+views[tab]()}
function run(){try{R=analyse();shown={};const p0=CFG.pol;CFG.pol=p0?0:1;try{R.alt=analyse()}finally{CFG.pol=p0}const s0=CFG.sup;CFG.sup=s0===1?0:1;try{R.altS=analyse()}finally{CFG.sup=s0}link();$('#app').hidden=false;$('#st').textContent='Analysed.';show()}catch(e){$('#st').textContent='Error: '+e.message}}
// Responsive paging: when the screen crosses the 600 px line (rotation, window resize), redraw the current tab once, 150 ms after the resizing stops.
// Only tabs holding a table longer than the narrow page (50 rows) can look different, so other tabs (and Settings inputs) are left alone.
// 'Show all' choices (shown{}), the Demand forecast SKU (fsku), the policy filter (pf) and the production-order toggle (prAll) live outside the drawn HTML, so they survive the redraw; the scroll position is restored.
// The browser may already have moved (clamped) the scroll position by the time the resize event arrives, so the position is remembered from scroll events that happened BEFORE the resize (lastY) and restored after the redraw.
let lastY=0,lastRz=-1e9;
if(typeof window!=='undefined'){window.addEventListener('scroll',()=>{if(performance.now()-lastRz>400)lastY=window.scrollY},{passive:true});
 window.addEventListener('resize',()=>{lastRz=performance.now();clearTimeout(rzT);rzT=setTimeout(()=>{if(typeof R==='undefined'||!R||pgSize()===lastPg)return;lastPg=pgSize();if(tblMax<=PAGE_NARROW)return;const y=lastY;show();window.scrollTo(0,y)},150)})}
// v0.7 A1: page bindings run only when a page is present (see excel-import.js). In the browser the behaviour is unchanged.
if(typeof document!=='undefined'){
document.addEventListener('change',e=>{if(e.target.id==='fsel'){fsku=e.target.value;show()}});
document.addEventListener('input',e=>{const k=e.target&&e.target.dataset&&e.target.dataset.k;if(k)setDraft[k]=e.target.value});
document.addEventListener('click',e=>{const t=(e.target.closest&&e.target.closest('[data-t],[data-pf],[data-pr],[data-more],#rc,#ex,#rs'))||e.target;if(t.dataset.t){tab=t.dataset.t;show()}if(t.dataset.pf!==undefined){pf=t.dataset.pf;show()}if(t.dataset.pr!==undefined){prAll=!prAll;show()}if(t.dataset.more!==undefined){const k=t.dataset.more,y=window.scrollY;shown[k]=t.dataset.all?1e9:Math.max(pgSize(),shown[k]||0)+pgSize();show();window.scrollTo(0,y)}
 if(t.id==='rc')applySettings();if(t.id==='rs'){Object.assign(CFG,CFG0);Object.keys(setDraft).forEach(k=>delete setDraft[k]);setMsg='All settings were reset to their defaults.';run()}
 if(t.id==='ex')exportWorkbook();});
}

// ---------- v0.6 additions: attainment, PO reconciliation, forecast credibility ----------
let prAll=false;
const demoBanner=()=>R.demo?`SIMULATED DEMONSTRATION ANALYSIS: this workbook describes itself as synthetic or test data (sheet “${esc(R.demo.sheet)}”). Do not present these results as real client work.`:'Analysis of the uploaded workbook. The source data has not been independently verified; estimates are labelled as estimates.';
const prCard=()=>{const a=R.pr,T=a.reduce((o,p)=>(o.n+=p.n,o.nQ+=p.nQ,o.pl+=p.planned,o.ac+=p.actual,o.ex+=p.exQ,o.s+=p.att==null?0:p.att*p.nQ,o),{n:0,nQ:0,pl:0,ac:0,ex:0,s:0}),avg=T.nQ?T.s/T.nQ:null,w=T.pl>0?T.ac/T.pl*100:null;
 return `<div class="card"><h2>Production schedule adherence and attainment (by SKU)</h2><div class="k"><div><b>${f(T.n)}</b><span>Production orders (${f(T.nQ)} with valid quantities)</span></div><div><b>${f(T.pl)}</b><span>Total planned quantity</span></div><div><b>${f(T.ac)}</b><span>Total actual quantity</span></div><div><b>${f(avg,1)}%</b><span>Average order attainment (mean of orders)</span></div><div><b>${f(w,1)}%</b><span>Overall weighted attainment (total actual ÷ total planned)</span></div></div>
 <p class="note"><b>Average order attainment</b> = mean of each order’s actual ÷ planned × 100. <b>Overall weighted attainment</b> = total actual ÷ total planned × 100. They differ because larger orders carry more weight in the weighted figure. Orders with a zero or missing planned quantity, or a missing completed quantity, are excluded from both and counted under Excluded; they are never treated as zero. ${T.ex?T.ex+' order(s) are excluded.':'No orders are excluded.'} Only a few orders per SKU: indicative.</p>
 ${tbl([['SKU',x=>x.id],['Orders',x=>x.n],['Orders used',x=>x.nQ],['Total planned',x=>f(x.planned)],['Total actual',x=>f(x.actual)],['Avg order attainment %',x=>f(x.att,1)],['Overall weighted attainment %',x=>f(x.wAtt,1)],['Excluded',x=>x.exQ],['Late orders',x=>x.lateN+'/'+x.nDL],['Late %',x=>f(x.late)],['Evidence',x=>x.n<5?'Low sample':'',1],['Avg slip d',x=>f(x.slip,1)]],prAll?a:a.slice(0,12),[['Product',1],['Quantities',4],['Attainment (two measures)',2],['',1],['Schedule',4]])}
 <button class="p" data-pr="1">${prAll?'Show top 12 only':'Show all '+a.length+' SKUs'}</button></div>`};
const poReconCard=()=>{const p=R.po,c=p.PC,q=v=>f(v),rows=[
 ['1. Total inventory on-order quantity (raw materials)',q(p.invRM),'Inventory sheet, On_Order_Qty'],
 ['2. Verified open purchase orders (status open, ordered on or before the snapshot, not received by it)',q(c.open.q)+' ('+c.open.n+' POs)','overdue (promised on or before snapshot): '+q(c.open.over)+'; not yet due: '+q(c.open.notDue)],
 ['3. Future-dated supply (marked received, but receipt dated after the snapshot)',q(c.fut.q)+' ('+c.fut.n+' POs)','counted as outstanding at the snapshot; overdue: '+q(c.fut.over)+'; not yet due: '+q(c.fut.notDue)],
 ['   Verified outstanding supply at snapshot (2 + 3)',q(p.snap),'used for inventory position when the supply source is PO-verified'],
 ['4. Received quantities excluded (received on or before the snapshot)',q(c.rec.ord)+' ordered; '+q(c.rec.qty)+' received ('+c.rec.n+' POs)','short-receipt balance treated as closed: '+q(c.rec.short)+(c.rec.noQty?'; '+c.rec.noQty+' with no received quantity':'')+(c.rec.undated?'; '+c.rec.undated+' marked received with no date':'')],
 ['5. Unreconciled quantity (1 minus verified supply)',q(p.gap),p.explained==null?'':f(p.explained*100,1)+'% of inventory on-order is supported by purchase orders'],
 ['6. Reconciliation status',p.status,p.mis+' of '+R.recon.length+' materials differ']];
 return `<h2>On-order reconciliation (raw materials, as at the snapshot date)</h2>${tbl([['Measure',x=>x[0],1],['Quantity',x=>x[1],1],['Detail',x=>x[2],1]],rows)}
 <p class="note">Not counted as supply: ordered after the snapshot ${q(c.after.q)} units (${c.after.n} POs); cancelled ${q(c.can.q)} units (${c.can.n} POs); unclassifiable (missing quantity or order date) ${c.bad.n} POs. Finished-goods On_Order_Qty (${q(p.invFG)} units) has no purchase-order source in the workbook. Status now (by PO status field): ${q(p.now)} units outstanding.</p>
 ${p.gap!==0?`<p class="note"><b>What this means.</b> A reconciliation difference has been detected between two source records (inventory On_Order_Qty and the Purchase Orders sheet). It cannot currently be explained from this workbook, because the purchase orders support only ${q(p.snap)} units as outstanding at the snapshot date. This is a data-reconciliation finding. It does not by itself show lost stock, incorrectly valued inventory or a purchasing error. The next step is to ask how the inventory system derives On_Order_Qty (see Client questions).</p>`:'<p class="note">Inventory on-order matches purchase orders at the snapshot date.</p>'}
 <p class="note"><b>Assumptions.</b> A PO received on or before the snapshot is closed, even if received short. A PO with a receipt dated after the snapshot is treated as fully outstanding at the snapshot. For open POs, partial-receipt dates are unknown, so the ordered quantity is treated as outstanding at the snapshot. Cancelled POs are not supply.</p>${reconCard()}`};
views['Forecast accuracy']=()=>{if(!R.hasF)return '<div class="card">No Forecast_Units data in this workbook, so historical forecast accuracy cannot be calculated. Nothing has been inferred.</div>';
 const C=fcCredAll(),A=fcAll(),rows=R.fg.map(x=>({x,c:C[x.id]})),ass=rows.filter(r=>r.c.dq!=='Insufficient'),hi=ass.filter(r=>r.c.hiAcc).length,avg=ass.length?mean(ass.map(r=>r.c.acc)):null,cnt=k=>rows.filter(r=>r.c.dir===k).length,dqc=k=>rows.filter(r=>r.c.dq===k).length,cf=k=>rows.filter(r=>r.c.conf===k).length,bt=rows.filter(r=>r.c.beats).length,many=ass.length&&hi/ass.length>=CFG.fcHighShare/100;
 const decl=new Set(R.declared||[]);
 return `<div class="card">${R.demo?`<div class="warn"><b>Demonstration data.</b> This workbook describes itself as synthetic or test data (sheet “${esc(R.demo.sheet)}”: “${esc(R.demo.text)}”). Patterns below are demonstration patterns. The engine did not use the workbook’s notes to produce any result; products mentioned in them are only tagged in the last column.</div><br>`:''}
 <p class="note">This compares the workbook’s recorded historical forecasts with actual sales. It is separate from the Demand forecast tab, which builds new forecasts. Three things are kept apart: <b>forecast performance</b> (how close the forecasts were), <b>data quality</b> (whether the history is complete enough to judge), and <b>confidence in the information</b> (how far the assessment can be trusted, not whether the forecast itself is good). Strong accuracy on thin or unusually consistent data is not reported as excellent forecasting.</p>
 <div class="k"><div><b>${f(avg,1)}%</b><span>Average accuracy (${ass.length} assessable products)</span></div><div><b>${cnt('Over-forecast')}/${cnt('Under-forecast')}/${cnt('Balanced')}</b><span>Over / under / balanced (±${CFG.fcBias}% band)</span></div><div><b>${dqc('Adequate')}/${dqc('Limited')}/${dqc('Insufficient')}</b><span>Data quality adequate / limited / insufficient</span></div><div><b>${cf('High')}/${cf('Medium')}/${cf('Low')}</b><span>Confidence high / medium / low</span></div></div>
 ${many?`<div class="warn"><b>Unusually consistent accuracy.</b> ${hi} of ${ass.length} products (${f(hi/ass.length*100)}%) show accuracy of ${CFG.fcHighAcc}% or more. This is not treated as a problem, but it is also not evidence of strong forecasting on its own: it is a prompt to validate how the forecasts were produced (for example, whether they were recorded before the period or derived from actual sales). The threshold is a heuristic and can be changed in Settings.</div><br>`:''}
 ${bt?`<p class="note">${bt} existing forecasts were more than twice as accurate as the best simple statistical method on the same months, which is another reason to verify their provenance.</p>`:''}
 ${tbl([['SKU',x=>x.x.id],['Accuracy %',x=>f(x.c.acc,1)],['WAPE %',x=>x.x.wape==null?'–':f(x.x.wape*100,1)],['Bias %',x=>f(x.c.bias,1)],['Direction',x=>x.c.dir||'–',1],['Bias units',x=>f(x.x.fcu)],['Bias £ at cost',x=>gbp(x.x.fcu*x.x.cost)],['Existing vs best simple method (WAPE %)',x=>x.c.wb==null?'n/a':f(x.c.wb*100,1)+' vs '+f(x.c.wbBest*100,1)],['Verdict',x=>x.c.verdict,1],
  ['Periods (used/expected)',x=>x.c.nV+'/'+x.c.expected],['Missing periods',x=>x.c.missing],['Zero-demand',x=>x.c.zeros],['Outliers',x=>x.c.out],['Forecast gaps',x=>x.c.fcMiss],['Data quality',x=>x.c.dq,1],
  ['Confidence',x=>x.c.conf],['Why',x=>x.c.confWhy+(x.c.confFix?' To raise confidence: '+x.c.confFix+'.':''),1],['Finding',x=>x.c.finding,1],['Workbook note',x=>decl.has(x.x.id)?'Mentioned in workbook test notes':'',1]],
  rows.sort((p,q)=>(q.c.acc==null)-(p.c.acc==null)||(q.c.acc??0)-(p.c.acc??0)),[['Product',1],['Forecast performance',8],['Data quality',6],['Confidence in the information',2],['Assessment',2]])}</div>
 ${(R.notes||[]).length?`<div class="card"><h2>Workbook notes (read from the file, not used in any calculation)</h2>${R.notes.map(n=>`<p class="note"><b>${esc(n.sheet)}</b></p>${n.rows.map(t=>`<p class="note">${esc(t)}</p>`).join('')}`).join('')}</div>`:''}`};

// ---------- v0.6: documented settings, plain-language confidence ----------
let setMsg='';
const setDraft={}; // unapplied Settings text, keyed by setting; separate from CFG (the applied configuration). Filled as you type, restored when Settings is redrawn, cleared by Apply (Recalculate) and Reset.
const SETDEF=[
// key,label,min,max,step,section,measures,why-default,if-changed,[affects label,class]
['basis','Demand months averaged',1,12,1,'Stock and demand','How many recent months are averaged to get monthly demand (and, through the BOM, material usage).','12 uses a full year, so seasonal highs and lows even out.','Fewer months react faster to recent change but are noisier. Every demand-based figure moves.',['Calculations','c']],
['excess','Excess stock threshold (days of cover)',1,365,1,'Stock and demand','Stock above this many days of demand is counted as potential excess.','90 days (about three months) is a common planning horizon for make-to-stock items; it is a judgement, not a standard.','Excess flags, potential excess £, dead-stock classes and health scores change. Nothing is a saving until verified.',['Calculations','c']],
['x','XYZ: X if demand variability (CV) at most',0,5,.01,'Stock and demand','Coefficient of variation (spread ÷ average) below which demand is called stable (X).','0.15 suits the very smooth demo data; real data usually needs about 0.5.','Changes the XYZ class, the volatile-demand warning, health score and confidence reason.',['Classification and warnings','w']],
['y','XYZ: Y if variability at most',0,5,.01,'Stock and demand','Variability above which demand is called erratic (Z).','0.25 for the same reason; real data usually needs about 1.0.','Changes the XYZ class (Y or Z), the volatile-demand warning, health score and confidence reason. Must be higher than the X value.',['Classification and warnings','w']],
['abcA','ABC: A items up to cumulative % of value',1,99,1,'Stock and demand','Share of annual consumption value covered by A items.','80% is the classic Pareto cut.','Only the A/B/C label changes.',['Classification only','w']],
['abcB','ABC: B items up to cumulative %',2,100,1,'Stock and demand','Cumulative share at which B ends and C starts.','95% completes the usual 80/15/5 split.','Only the A/B/C label changes. Must be higher than the A value.',['Classification only','w']],
['z','Service level (z-score)',0,4,.05,'Safety stock and policy','Safety-stock multiplier: 1.65 is about a 95% chance of not running out during a lead time, if demand is roughly normal.','1.65 (95%) is a widely used starting service level.','Recommended safety stock and reorder points change, and risk classes when the calculated policy is selected. Workbook values are never overwritten.',['Calculations','c']],
['pol','Policy driving risk (0 workbook, 1 calculated)',0,1,1,'Safety stock and policy','Which safety-stock and reorder-point values decide risk classes.','0 respects the business’s own settings; the calculated policy is shown alongside.','Switching changes risk classes (see the Policy comparison tab).',['Calculations','c']],
['hold','Holding cost % per year (illustration)',0,100,1,'Safety stock and policy','Annual cost of holding stock, used only for the illustrative holding-cost line.','20% is an illustrative round number; set your own.','Only the illustrative £ figure on the Overview changes.',['Display only','d']],
['sup','Supply source (0 verified POs, 1 inventory on-order, 2 verified plus comparison)',0,2,1,'Supply and lead times','Which on-order figure feeds inventory position, MRP and feasibility.','0 counts only purchase orders that can be verified at the snapshot date.','Position cover, risk classes, MRP and feasibility change.',['Calculations','c']],
['fgLT','Default lead time when none exists (days)',1,365,1,'Supply and lead times','Fallback used only when a product has no supplied lead time and no usable production history.','7 days is a placeholder so calculations can run; it is labelled Assumed wherever used.','Only products without history change.',['Calculations','c']],
['late','Add supplier lateness to lead time (0 or 1)',0,1,1,'Supply and lead times','Whether average supplier lateness is added to the stated material lead time.','1 because stated lead times usually understate real delivery.','Material lead times, cover tests, reorder points and MRP change.',['Calculations','c']],
['ltMinN','Production orders needed for a reliable lead time',1,50,1,'Supply and lead times','Number of production orders before a calculated lead time is labelled Calculated rather than Estimated.','5 is a small-sample rule of thumb.','Labels and the lead-time confidence reason change; lead-time values do not.',['Labels and confidence only','w']],
['ltMinSup','POs needed for a reliable supplier lateness',1,200,1,'Supply and lead times','Scored purchase orders before a supplier lateness adjustment is treated as reliable.','30 is the usual rule of thumb for a stable average.','Labels and confidence change; the adjustment itself does not.',['Labels and confidence only','w']],
['hor','MRP horizon (months)',1,12,1,'Planning','Months ahead that MRP plans material needs.','3 months matches a typical purchasing cycle.','Gross and net requirements and suggested quantities change.',['Calculations','c']],
['grace','Supplier on-time grace (days)',0,30,1,'Suppliers','Days after the promised date that still count as on time.','0 means strictly on or before the promised date.','Supplier on-time %, score and risk class change.',['Calculations','c']],
['otd','Supplier on-time warning level (%)',0,100,1,'Suppliers','On-time percentage below which a supplier is called unreliable in warnings.','40% flags only clearly weak suppliers.','Warning shading, the health-score penalty and the At risk feasibility status change.',['Warnings, health score and feasibility status','w']],
['supLow','Supplier class: Low risk from score',1,100,1,'Suppliers','Supplier score at or above which a supplier is Low risk.','75 and 60 are round-number bands on a 0 to 100 score; they are judgement. The score formula is fixed.','Risk class text, confidence and the weak-supplier recommendation change; scores do not.',['Classification and warnings','w']],
['supMed','Supplier class: Medium risk from score',0,99,1,'Suppliers','Score below which a supplier is High risk.','60 is the lower round-number band, matching the Low-risk value above; it is a judgement.','Changes the supplier risk class (Medium or High), confidence and the weak-supplier recommendation; scores do not change. Must be lower than the Low-risk value.',['Classification and warnings','w']],
['supMinPO','Scored POs for adequate supplier evidence',1,100,1,'Suppliers','Number of scored purchase orders before supplier evidence is Adequate rather than Limited.','10 gives a rough but usable picture.','Evidence labels and the Performance problem versus Possible problem wording change.',['Labels only','w']],
['fcH','Forecast horizon shown (months)',3,12,1,'Forecasting','Months in the forecast total column.','12 shows a full year.','Display only; the chart and forecasts are unchanged.',['Display only','d']],
['fcTest','Forecast back-test months',3,6,1,'Forecasting','How many past months are used to test each method before choosing one.','6 gives the most test points a 12-month history allows.','The chosen method, and so the forecast, can change.',['Calculations','c']],
['fcHighAcc','Forecast accuracy flagged unusually high at (%)',50,100,1,'Forecast credibility','Accuracy at or above this is flagged as unusually high, to be validated.','95 is a high round bar; a heuristic, not an industry standard.','Only warnings and findings change; accuracy figures do not.',['Warnings only','w']],
['fcHighShare','Dataset warning when this % of products are flagged',0,100,1,'Forecast credibility','Share of assessable products above the accuracy bar before the dataset-wide warning appears.','50 means a majority.','Only the dataset-wide warning changes.',['Warnings only','w']],
['fcBias','Forecast bias: balanced within ± (%)',0,50,1,'Forecast credibility','Bias inside this band is called Balanced; outside it, Over or Under.','10% is a common round tolerance; a heuristic.','Direction labels and findings change; bias values do not.',['Warnings only','w']],
['fcBiasShare','Bias counted as consistent if same direction in (% of periods)',50,100,1,'Forecast credibility','Share of periods that must lean the same way for bias to be called consistent.','75% means three periods in four.','Only the Consistent versus not wording changes.',['Warnings only','w']],
['outZ','Outlier threshold (robust z-score)',2,10,.1,'Forecast credibility','How far a month sits from typical demand (median and MAD) before it is called an outlier.','3.5 is the cut-off commonly recommended for this robust measure (Iglewicz and Hoaglin).','Data-quality rating and confidence change; forecasts do not.',['Warnings only','w']],
['fcMinN','Minimum periods to assess a forecast',3,12,1,'Forecast credibility','Paired forecast and actual periods needed before accuracy is assessed at all.','6 is half a year, the least that shows a pattern.','Cannot assess labels change. Must be lower than the next value.',['Warnings only','w']],
['fcAdeqN','Periods for adequate history',4,36,1,'Forecast credibility','Periods needed before history is called adequate; also the short-history confidence reason for stock items.','12 is one full year.','Data-quality ratings and confidence reasons change; calculations do not.',['Warnings only','w']]];
function applySettings(){const msgs=[];
 SETDEF.forEach(([k,label,min,max])=>{const el=document.querySelector('[data-k="'+k+'"]');if(!el)return;let v=el.value.trim()===''?NaN:+el.value;
  if(!isFinite(v)){msgs.push(label+': not a number, reset to the default ('+CFG0[k]+').');v=CFG0[k]}else if(v<min){msgs.push(label+': below the minimum, set to '+min+'.');v=min}else if(v>max){msgs.push(label+': above the maximum, set to '+max+'.');v=max}
  if(['basis','hor','fcH','fcTest','sup','pol','late','fcMinN','fcAdeqN','ltMinN','ltMinSup','supMinPO'].includes(k))v=Math.round(v);CFG[k]=v});
 [['x','y','XYZ X must be lower than Y'],['abcA','abcB','ABC A must be lower than B'],['supMed','supLow','Supplier Medium cut-off must be lower than Low-risk cut-off'],['fcMinN','fcAdeqN','Minimum periods must be lower than adequate periods']].forEach(([lo,hi,m])=>{if(CFG[lo]>=CFG[hi]){msgs.push(m+'; both reset to their defaults.');CFG[lo]=CFG0[lo];CFG[hi]=CFG0[hi]}});
 Object.keys(setDraft).forEach(k=>delete setDraft[k]);setMsg=msgs.join(' ');run()}
views.Settings=()=>{const secs=[...new Set(SETDEF.map(s=>s[5]))];
 return `<div class="card">${setMsg?`<div class="warn">${esc(setMsg)}</div><br>`:''}<p class="note">Every threshold is a judgement call unless stated. Each shows its default, why that default was chosen, what changes when you change it, and whether it alters calculations or only warnings and labels. Values outside the allowed range are corrected and you are told.</p>
 ${secs.map(sc=>`<h2>${esc(sc)}</h2>${SETDEF.filter(s=>s[5]===sc).map(([k,label,min,max,step,,what,why,chg,aff])=>`<div class="set"><label><b>${esc(label)}</b> <input type="number" step="${step}" min="${min}" max="${max}" data-k="${k}" value="${esc(String(setDraft[k]!==undefined?setDraft[k]:CFG[k]))}"> <span class="note">default ${CFG0[k]}, allowed ${min} to ${max}</span></label><p class="note"><b>Measures:</b> ${esc(what)} <b>Why this default:</b> ${esc(why)} <b>If changed:</b> ${esc(chg)}</p><span class="tag t-${aff[1]}">Affects: ${esc(aff[0])}</span></div>`).join('')}`).join('')}
 <h2>Fixed rules (not configurable)</h2><p class="note">Seasonal forecasts need 24 months, because seasonal indices cannot be estimated from less than two annual cycles. The MAD scale factor 1.4826 makes the robust z-score comparable to a standard deviation. Two or more consecutive extreme months are treated as a level shift, not as outliers, and lower forecast-assessment confidence by one level (accuracy and verdict are not affected). When most months equal the median (median absolute deviation of zero) the outlier test cannot run, and the page says so. A production order counts as at least 1 day. Finished-goods safety stock assumes a fixed production time: production-time variability is not included, although raw-material safety stock does include supplier lead-time variability. The supplier score weights (50% on-time, 20% lead-time stability, 15% fill rate, 15% lateness) are fixed; only the class bands are adjustable.</p>
 <button class="p" id="rc">Recalculate</button> <button class="p" id="rs">Reset to defaults</button> <button class="p" id="ex">Export to Excel</button> <button class="p" onclick="print()">Print report</button></div>`};
const CONF_TXT={
 'consumption estimated from BOM, not recorded':['Material use is estimated from product sales and the bill of materials, not recorded.','provide goods-issue or usage records'],
 'short demand history':['There is less demand history than the adequate-history setting.','provide 24–36 months of demand'],
 'data-quality flag on this item':['This item’s own data failed a quality check (see Data quality).','correct the flagged records'],
 'volatile demand':['Demand swings a lot from month to month, so averages are less dependable.','review safety stock regularly and provide more history'],
 'supplier has no delivery history':['The supplier has no received orders to measure, so lateness could not be calculated (it is not assumed to be zero).','provide the supplier’s delivery history'],
 'lead time rests on a small or unreliable supplier sample':['The lead time relies on few deliveries or on a supplier with a weak record.','provide longer supplier delivery history'],
 'lead time is a proxy from too few production orders':['The lead time is estimated from too few production orders.','provide a supplied lead time or more production history'],
 'risk class changes with the supply source (on-order does not reconcile to POs)':['The risk class depends on which on-order figure is used, and the two do not reconcile.','confirm how On_Order_Qty is calculated'],
 [NODEM]:['No demand is recorded, so cover and risk cannot be judged.','confirm whether the item is still sold or used']};
const confExplain=x=>{const t=x.cw.map(w=>CONF_TXT[w]||[w,'']),head={High:'Reliable: it rests on recorded data and no material limitation was found.',Medium:'Fairly reliable, with one limitation. ',Low:'Uncertain. ','Cannot assess':'Cannot be assessed. '}[x.conf]||'',fix=[...new Set(t.map(z=>z[1]).filter(Boolean))];return head+(x.conf==='High'?'':t.map(z=>z[0]).join(' '))+(fix.length?' To raise confidence: '+fix.join('; ')+'.':'')};
function confAreas(){const A=[...R.fg,...R.rm],N=A.length,c=k=>A.filter(x=>x.conf===k).length,rs={};A.forEach(x=>x.cw.forEach(w=>rs[w]=(rs[w]||0)+1));
 const top=Object.entries(rs).sort((a,b)=>b[1]-a[1]).slice(0,3),topTxt=top.map(([w,n])=>n+' items: '+(CONF_TXT[w]||[w])[0]).join(' ')||'No limitations were found.',topFix=[...new Set(top.map(([w])=>(CONF_TXT[w]||['',''])[1]).filter(Boolean))].join('; ')||'nothing further needed';
 const lvl=(h,m,l,ca)=>{const n=h+m+l+ca;return !n?'Cannot assess':h/n>=.7?'High':(l+ca)/n>=.5?'Low':'Medium'},out=[];
 out.push({area:'Stock position and shortage risk',rating:lvl(c('High'),c('Medium'),c('Low'),c('Cannot assess')),why:`${c('High')} high, ${c('Medium')} medium, ${c('Low')} low and ${c('Cannot assess')} cannot be assessed, out of ${N} items. Main reasons: ${topTxt}`,improve:topFix});
 const bl=Object.values(R.bomS).reduce((s,a)=>s+a.length,0);out.push({area:'Raw-material usage',rating:bl?'Medium':'Cannot assess',why:bl?`Material use is calculated from sales and the bill of materials (${bl} BOM lines). It is an estimate and is never a recorded figure.`:'There is no bill of materials, so usage cannot be estimated.',improve:'provide goods-issue or usage records'});
 const L=A,src=(re)=>L.filter(x=>re.test(x.ltInfo.source)).length,sS=src(/^Supplied/),sC=src(/^Calculated/),sE=src(/^Estimated/),sA=src(/^Assumed/),weak=R.rm.filter(x=>!x.ltInfo.enough).length;
 out.push({area:'Lead times',rating:sA>0||(sE+sA)/N>=.5?'Low':(sE>0||weak>0)?'Medium':'High',why:`${sS} supplied, ${sC} calculated, ${sE} estimated from a limited sample and ${sA} assumed from a default setting. ${weak} material lead time(s) add a supplier-lateness adjustment based on limited or no history.`,improve:'provide supplied lead times and longer supplier or production history'});
 const ev=k=>R.sup.filter(s=>s.evid===k).length,NS=R.sup.length;
 const poBad=R.dq.filter(d=>d.sheet==='Purchase Orders'&&d.sev==='High'&&/Duplicate records|Impossible quantities|Non-numeric quantity/.test(d.msg)).length; // definite PO data faults feed the supplier scores, so they cap confidence at Medium
 const supBase=!NS?'Cannot assess':(ev('None')+ev('Limited'))===0?'High':(ev('None')+ev('Limited'))/NS>=1/3?'Low':'Medium';
 out.push({area:'Supplier performance',rating:supBase==='High'&&poBad?'Medium':supBase,why:`${ev('Adequate')} supplier(s) have adequate delivery history, ${ev('Limited')} limited and ${ev('None')} none (${SUP_NA}, and not treated as good or bad${R.sup.some(s=>s.reason==='Data problem')?'; '+R.sup.filter(s=>s.reason==='Data problem').length+' of them because purchase-order quantities or dates are invalid':''}).`+(poBad?` ${poBad} purchase-order data problem(s) of High severity (duplicate PO numbers, impossible or non-numeric quantities) are flagged in Data quality. Non-numeric and negative quantities are left out of the fill rate and never lower a score, but duplicate and over-received lines are still counted, so treat the scores with caution until they are corrected.`:''),improve:'provide delivery history for suppliers with limited or no received orders'});
 if(R.hasF){const C=fcCredAll(),v=Object.values(C),k=q=>v.filter(z=>z.conf===q).length,hi=v.filter(z=>z.hiAcc).length;out.push({area:'Forecast accuracy assessment',rating:lvl(k('High'),k('Medium'),k('Low'),0),why:`${k('High')} high, ${k('Medium')} medium and ${k('Low')} low confidence across ${v.length} products; ${hi} show unusually high accuracy that should be validated.`,improve:'provide 24–36 months of history and confirm how forecasts were produced'})}else out.push({area:'Forecast accuracy assessment',rating:'Cannot assess',why:'The workbook has no recorded historical forecasts.',improve:'provide historical forecasts alongside actual demand'});
 const p=R.po,pr=p.status==='Reconciled'?'High':/^(Mostly|Totals match)/.test(p.status)?'Medium':/^Cannot/.test(p.status)?'Cannot assess':'Low';
 out.push({area:'On-order and purchase-order reconciliation',rating:pr,why:`${p.status}. ${f(p.gap)} of ${f(p.invRM)} on-order units cannot be matched to purchase orders${p.explained==null?'':' ('+f(p.explained*100,1)+'% supported)'}.`,improve:'obtain the open purchase-order ledger and confirm how On_Order_Qty is calculated'});
 out.push({area:'Material requirements planning',rating:(pr==='Low'||CFG.sup===1)?'Low':'Medium',why:`MRP holds demand flat at its average, and its supply side depends on the on-order figure (currently ${SRC()}).`,improve:'resolve the reconciliation and feed forecasts into the plan'});
 out.push({area:'Production feasibility',rating:openPR().length?'Medium':'Low',why:openPR().length?'Based on the workbook’s open production orders; materials only, with no capacity or routing data.':'The workbook has no open production orders, so feasibility is shown on illustrative orders only.',improve:'provide open and planned production orders'});
 return out}
views['Data confidence']=()=>{const a=confAreas(),cl={High:'s0',Medium:'s1',Low:'s2','Cannot assess':'s3'};
 return `<div class="card"><h2>How much can you rely on these results?</h2><p class="note">Confidence is about the evidence behind a figure, not about whether the result is good. A High rating does not mean the business is performing well; a Low rating on a worrying result means check the data first.</p>
 ${tbl([['Rating',x=>H(`<span class="${x[1]}">${x[0]}</span>`),1],['Meaning',x=>x[2],1]],[['High','s0','Built on recorded data with adequate history and no material limitation found.'],['Medium','s1','Usable, with one limitation. Read the reason before relying on it.'],['Low','s2','Two or more limitations. Treat as a pointer to investigate, not a conclusion.'],['Cannot assess','s3','The data needed to judge is missing, for example no demand, too few periods or no purchase orders.']])}</div>
 <div class="card"><h2>Confidence by area</h2>${tbl([['Area',x=>x.area,1],['Rating',x=>H(`<span class="${cl[x.rating]}">${esc(x.rating)}</span>`),1],['Why',x=>x.why,1],['What would raise it',x=>x.improve,1]],a)}<p class="note">Item-level reasons appear in the Confidence basis column of the Finished goods and Materials tabs, and the forecast reasons on the Forecast accuracy tab. Area ratings are rules over those item ratings: High when at least 70% of items are High, Low when at least half are Low or cannot be assessed, otherwise Medium.</p></div>`};
